`import React, { useState } from 'react';
import { ChevronDown, Zap, Sparkles, Check, Info, X, Sparkle } from 'lucide-react';

const FAQ_DATA = [
  {
    id: 1,
    title: 'How do I start using Flowboard?',
    body: 'Simply sign up for a free account and connect your calendar. Flowboard automatically turns your meeting notes into actionable tasks. No setup required.',
    icon: Zap,
    active: false,
  },
  {
    id: 2,
    title: 'Can Flowboard integrate with other project management tools?',
    body: 'Absolutely! We seamlessly sync with Jira, Trello, Slack, and more via our API connectors and Zapier integrations.',
    icon: Zap,
    active: false,
  },
  {
    id: 3,
    title: 'What kind of data is captured during a meeting?',
    body: 'Flowboard extracts key points, decisions, action items, and participants from your meeting recordings. We prioritize privacy and use advanced NLP to ensure accuracy.',
    icon: Sparkles,
    active: false,
  },
  {
    id: 4,
    title: 'Is there a mobile app?',
    body: 'Yes, our native mobile app is available for both iOS and Android. Stay productive on-the-go and sync seamlessly across devices.',
    icon: Sparkles,
    active: false,
  },
  {
    id: 5,
    title: 'How does the pricing tier work?',
    body: 'We offer flexible pricing plans starting at $12/user/month. All tiers include unlimited task management, integrations, and priority support.',
    icon: Sparkles,
    active: false,
  },
];

export default function Faq() {
  const [activeQ, setActiveQ] = useState<number | null>(null);
  const [isMobile, setIsMobile] = useState(false);

  const toggleAccordion = (id: number) => {
    if (activeQ === id) {
      setActiveQ(null);
    } else {
      setActiveQ(id);
    }
  };

  return (
    <div className="w-full bg-slate-950 p-4 sm:p-6 lg:p-8 text-slate-100">
      <div className="max-w-7xl mx-auto">
        <div className="mb-12 flex flex-col items-center justify-center text-center">
          <div className="inline-flex items-center gap-2 rounded-full bg-white/5 p-3 text-slate-400 shadow-lg backdrop-blur-xl">
            <Sparkles className="w-5 h-5 animate-pulse" />
            <span className="text-sm font-semibold tracking-wide text-slate-300">FAQ & Support</span>
          </div>
          <h2 className="mt-4 text-2xl font-bold tracking-tight text-slate-100 sm:text-3xl">Got Questions? We Got Answers.</h2>
          <p className="max-w-md mt-3 text-slate-400 text-sm sm:text-base">Explore our detailed guide to maximizing Flowboard's features and capabilities.</p>
        </div>

        <div className="w-full max-w-2xl mx-auto divide-y divide-white/10 rounded-2xl bg-white/5 p-6 sm:p-8 lg:p-10 shadow-2xl transition-all duration-300 hover:shadow-indigo-500/10">
          {FAQ_DATA.map((faq, idx) => {
            const isActive = activeQ === faq.id || (isMobile && idx === 0);
            return (
              <div key={faq.id} className="py-6 transition-all duration-300 hover:shadow-indigo-500/20">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4">
                  <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                    <div className="flex items-center gap-2">
                      {isActive ? (
                        <Check className="w-5 h-5 text-emerald-400 animate-pulse" />
                      ) : (
                        <Info className="w-5 h-5 text-cyan-400" />
                      )}
                      <h3 className="text-sm font-semibold text-slate-100">{faq.title}</h3>
                    </div>
                    {isActive ? (
                      <button
                        onClick={() => setActiveQ(null)}
                        className="inline-flex items-center gap-1.5 text-slate-400 hover:text-slate-100 transition-colors"
                      >
                        <X className="w-4 h-4" /> Close
                      </button>
                    ) : (
                      <button
                        onClick={() => setActiveQ(faq.id)}
                        className="inline-flex items-center gap-1.5 text-slate-400 hover:text-emerald-400 transition-colors"
                      >
                        <ChevronDown className="w-4 h-4" /> Details
                      </button>
                    )}
                  </div>
                  {isActive && (
                    <div className="flex items-center gap-2">
                      <div className="inline-flex items-center gap-1.5 bg-indigo-600/10 px-3 py-1 rounded-full text-xs font-medium text-indigo-300">
                        <Sparkle className="w-3 h-3" /> Active
                      </div>
                      <span className="inline-flex items-center gap-1.5 rounded-full bg-white/5 px-3 py-1 text-xs font-medium text-slate-400">
                        <Sparkles className="w-3 h-3" /> Section
                      </span>
                    </div>
                  )}
                </div>
                {isActive && (
                  <div className="prose max-w-none prose-a:no-underline prose-a:text-slate-400 prose-a:hover:text-indigo-400 mx-auto sm:max-w-none">
                    <p>{faq.body}</p>
                  </div>
                )}
              </div>
            );
          })}

          <div className="flex justify-center py-6">
            <button
              onClick={() => setIsMobile(true)}
              className="inline-flex items-center gap-2 rounded-xl bg-white/5 p-4 font-medium text-slate-400 hover:bg-white/10 hover:text-slate-100 transition-all duration-300"
            >
              <Sparkles className="w-5 h-5" /> Mobile Toggle
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
