`import React, { useState } from 'react';
import { Zap, Check, Shield, ArrowRight, Sparkles, Sparkle, DollarSign, UserPlus, ShieldAlert, Circle as SparkleCheck, ChevronRight, X } from 'lucide-react';

const PLANS = [
  {
    id: 'free',
    name: 'Free',
    price: '0',
    features: [
      'Sync with 1 active workspace',
      'Basic meeting summarization',
      'Daily digest emails',
      '20 tasks per month',
      'Limited integrations',
    ],
    isPopular: true,
    isDefault: true,
  },
  {
    id: 'pro',
    name: 'Pro',
    price: '14',
    features: [
      'Sync with up to 5 workspaces',
      'Advanced summarization & categorization',
      'Instant task creation',
      'Unlimited tasks',
      'Advanced integrations (Slack, Trello)',
    ],
    isHighlighted: true,
    isDefault: true,
  },
  {
    id: 'enterprise',
    name: 'Enterprise',
    price: '49',
    features: [
      'Unlimited workspace sync',
      'Real-time task collaboration',
      'Priority queue & alerts',
      'Custom branding & support',
      '24/7 SLA uptime guarantee',
    ],
    isHighlighted: true,
    isDefault: false,
  },
];

export default function Pricing() {
  const [activePlan, setActivePlan] = useState('pro');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const togglePlan = (id) => {
    setActivePlan(id);
  };

  const [formData, setFormData] = useState({
    name: '',
    company: '',
    email: '',
    workspace: 'Default Workspace',
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsModalOpen(true);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center p-6 sm:p-12 relative overflow-hidden font-sans">
      {/* Decorative Gradient Background */}
      <div className="absolute -top-48 -left-48 w-96 h-96 bg-indigo-600/20 rounded-3xl blur-3xl pointer-events-none" />

      {/* Top Gradient Border */}
      <div className="absolute -bottom-40 -left-24 w-200 h-1 bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-600 rounded-t-3xl" />

      {/* Main Pricing Cards Container */}
      <div className="w-full max-w-2xl mx-auto relative z-10">
        {/* Decorative Glassmorphism Decorations */}
        <div className="absolute top-1/4 -left-24 w-48 h-48 bg-white/5 border border-white/10 rounded-2xl shadow-lg backdrop-blur-xl flex items-center justify-center pointer-events-none">
          <Sparkles className="w-10 h-10 text-indigo-400" />
        </div>
        <div className="absolute bottom-1/4 -right-24 w-48 h-48 bg-white/5 border border-white/10 rounded-2xl shadow-lg backdrop-blur-xl flex items-center justify-center pointer-events-none">
          <Sparkles className="w-10 h-10 text-indigo-400" />
        </div>

        {/* Header Decorative Glow Background */}
        <div className="relative mb-16">
          <div className="absolute inset-0 bg-white/5 backdrop-blur-xl rounded-2xl pointer-events-none" />
          <div className="relative p-4 sm:p-6 bg-white/10 border border-white/10 rounded-2xl shadow-2xl backdrop-blur-xl">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-3xl font-bold tracking-tight text-slate-100">Pricing Plans</h2>
                <p className="text-slate-400 mt-2 text-sm">Elevate your team's productivity with Flowboard's seamless collaboration suite.</p>
              </div>
              <div>
                <button
                  onClick={() => setIsModalOpen(true)}
                  className="inline-flex items-center gap-2 px-3 py-2 rounded-xl bg-indigo-600/10 border border-indigo-500/20 text-indigo-300 hover:bg-indigo-600/20 transition-colors active:scale-95 duration-300 text-sm font-medium"
                >
                  <UserPlus className="w-4 h-4" />
                  <span>Create Workspace</span>
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Individual Plan Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 w-full max-w-md mx-auto">
          {PLANS.map((plan) => {
            const { id, name, price, features, isPopular, isHighlighted } = plan;
            return (
              <div
                key={id}
                className="relative overflow-hidden rounded-2xl border border-white/10 bg-white/5 backdrop-blur-xl transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl hover:border-white/20"
              >
                {/* Top Background Decorations */}
                <div className="absolute top-0 left-0 w-full h-1/3 bg-indigo-600/20" />
                <div className="absolute bottom-0 left-0 w-full h-1/3 bg-purple-600/20" />

                {/* Plan Card Header */}
                <div className="p-6 sm:p-8 flex flex-col justify-between h-full">
                  <div>
                    <h3 className="text-xl font-semibold tracking-tight text-slate-200 flex items-center gap-2">
                      {name}
                      {isPopular && <Sparkle className="w-4 h-4 text-indigo-400" />}
                    </h3>
                    <p className="text-sm text-slate-400 mt-1 flex items-center gap-2">
                      <span className="text-xl font-bold">{price}</span>
                      <span className="text-xs text-slate-500">/mo</span>
                    </p>
                    <ul className="mt-4 space-y-2 text-sm text-slate-400">
                      {features.map((f, i) => (
                        <li key={i} className="flex items-center gap-2">
                          <Check className="w-3 h-3 text-emerald-400" />
                          {f}
                        </li>
                      ))}
                    </ul>
                  </div>
                  <button
                    onClick={() => togglePlan(id)}
                    className="inline-flex items-center justify-center w-full py-3 text-sm font-semibold tracking-wide text-slate-100 bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-600 border border-transparent rounded-xl hover:scale-102 hover:shadow-lg transition-transform duration-200 active:scale-100"
                  >
                    {id === 'pro' ? 'Active' : 'Select'}
                    <ArrowRight className="w-4 h-4 ml-2" />
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {/* Modal for New Workspace Setup */}
        <div
          className={`fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-md transition-all duration-300 ${
            isModalOpen ? 'pointer-events-auto' : 'pointer-events-none opacity-0'
          }`}
        >
          <div className="relative w-full max-w-md overflow-hidden rounded-2xl bg-white/10 backdrop-blur-xl border border-white/10 p-6 shadow-2xl transition-all duration-300">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h2 className="text-xl font-bold tracking-tight text-slate-100">New Workspace Setup</h2>
                <p className="text-sm text-slate-400">Enter details to start using Flowboard.</p>
              </div>
              <button
                onClick={() => setIsModalOpen(false)}
                className="text-slate-400 hover:text-slate-200 transition-colors duration-200"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="relative">
                  <label htmlFor="name" className="block text-sm font-medium text-slate-400">Workspace Name</label>
                  <input
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg py-2 pl-4 pr-10 text-slate-100 focus:ring-2 focus:ring-indigo-500/30 transition-all outline-none placeholder:text-slate-500"
                    placeholder="Enter a name for your workspace"
                  />
                </div>
                <div className="relative">
                  <label htmlFor="company" className="block text-sm font-medium text-slate-400">Company</label>
                  <input
                    id="company"
                    value={formData.company}
                    onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                    className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg py-2 pl-4 pr-10 text-slate-100 focus:ring-2 focus:ring-indigo-500/30 transition-all outline-none placeholder:text-slate-500"
                    placeholder="Company name (optional)"
                  />
                </div>
              </div>
              <div className="relative">
                <label htmlFor="email" className="block text-sm font-medium text-slate-400">Your Email</label>
                <input
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg py-2 pl-4 pr-10 text-slate-100 focus:ring-2 focus:ring-indigo-500/30 transition-all outline-none placeholder:text-slate-500"
                  placeholder="Enter your company email"
                />
              </div>
              <div className="relative">
                <label htmlFor="workspace" className="block text-sm font-medium text-slate-400">Default Workspace</label>
                <select
                  id="workspace"
                  value={formData.workspace}
                  onChange={(e) => setFormData({ ...formData, workspace: e.target.value })}
                  className="w-full bg-slate-900/50 border border-slate-700/50 rounded-lg py-2 pl-4 pr-10 text-slate-100 focus:ring-2 focus:ring-indigo-500/30 transition-all outline-none placeholder:text-slate-500"
                >
                  <option value="">Select a default workspace</option>
                  <option value="sales">Sales & Deals Tracker</option>
                  <option value="marketing">Marketing & Campaigns</option>
                  <option value="engineering">Dev & CI/CD Pipeline</option>
                </select>
              </div>
              <button
                type="submit"
                className="inline-flex items-center justify-center w-full py-3 text-sm font-semibold tracking-wide text-slate-100 bg-indigo-600 border border-indigo-600 rounded-lg hover:bg-indigo-500 transition-all duration-300"
              >
                Start
                <span className="ml-2">
                  <ArrowRight className="w-4 h-4" />
                </span>
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}

